{
  "findings": [
    {
      "check_id": "CKV_AWS_52",
      "title": "Elastic IP associated with an instance",
      "resource": "aws_eip.ip",
      "severity": "MEDIUM",
      "explanation": "Elastic IPs are public by default, which can expose the associated instance to the internet. This increases the attack surface if the instance is not properly secured."
    }
  ],
  "patched_code": "resource \"aws_eip\" \"ip\" {\n  instance = aws_instance.MyFirstInstnace.id\n  vpc      = true\n}",
  "fix_summary": "Added the 'vpc' attribute to the Elastic IP resource to ensure it is associated with a VPC, which is a best practice for securing public IPs."
}
